import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.DYd_c05j.js";const u=JSON.parse('{"title":"Fixer dispatch contract v1","description":"","frontmatter":{},"headers":[],"relativePath":"fixer-dispatch-contract-v1.md","filePath":"fixer-dispatch-contract-v1.md","lastUpdated":null}'),s={name:"fixer-dispatch-contract-v1.md"};function n(d,e,r,c,l,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="fixer-dispatch-contract-v1" tabindex="-1">Fixer dispatch contract v1 <a class="header-anchor" href="#fixer-dispatch-contract-v1" aria-label="Permalink to &quot;Fixer dispatch contract v1&quot;">​</a></h1><blockquote><p><strong>Legacy migration boundary.</strong> ADR 0024 supersedes Fixer as a product role with the vendor-neutral <code>REMEDIATION_WORKER_V1</code> pull protocol. This contract remains valid only while the in-tree OpenCode runtime is migrated and must not dispatch the same task concurrently with a remediation worker lease.</p></blockquote><h2 id="scope-and-identities" tabindex="-1">Scope and identities <a class="header-anchor" href="#scope-and-identities" aria-label="Permalink to &quot;Scope and identities&quot;">​</a></h2><p>Fixer is the only external OpenCode worker. Chat and Task Router use direct, tool-free provider inference in the core API and are not part of this contract.</p><p>The automated worker owns the distinct MCP/task identity <code>agent:fixer</code>; an interactive OpenCode client remains <code>agent:opencode</code>. Tokens and identities are never shared. Infrastructure access remains exclusively through Homelab Console MCP and <code>execute_tool</code>, including approval, policy, validation, redaction and audit.</p><h2 id="http-supervisor-api" tabindex="-1">HTTP supervisor API <a class="header-anchor" href="#http-supervisor-api" aria-label="Permalink to &quot;HTTP supervisor API&quot;">​</a></h2><p>The supervisor binds only to loopback, with default port <code>8767</code>.</p><h3 id="get-health" tabindex="-1"><code>GET /health</code> <a class="header-anchor" href="#get-health" aria-label="Permalink to &quot;`GET /health`&quot;">​</a></h3><p>Returns <code>200</code>:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;active&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>active</code> is the number of locally running task processes. Other paths return <code>404 {&quot;ok&quot;:false,&quot;code&quot;:&quot;not_found&quot;}</code>.</p><h3 id="post-fixer" tabindex="-1"><code>POST /fixer</code> <a class="header-anchor" href="#post-fixer" aria-label="Permalink to &quot;`POST /fixer`&quot;">​</a></h3><p>Requires:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">X-Secret</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;FIXER_DISPATCH_SECRET&gt;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The body is limited to 4096 bytes and must contain exactly one UUID field:</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;task_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;00000000-0000-4000-8000-000000000000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>No prompt, command, target, model or tool is caller-selectable.</p><table tabindex="0"><thead><tr><th>Status</th><th>Body</th></tr></thead><tbody><tr><td><code>202</code></td><td><code>{&quot;ok&quot;:true,&quot;code&quot;:&quot;accepted&quot;}</code></td></tr><tr><td><code>400</code></td><td><code>{&quot;ok&quot;:false,&quot;code&quot;:&quot;invalid_input&quot;}</code> or <code>invalid_json</code></td></tr><tr><td><code>403</code></td><td><code>{&quot;ok&quot;:false,&quot;code&quot;:&quot;unauthorized&quot;}</code></td></tr><tr><td><code>404</code></td><td><code>{&quot;ok&quot;:false,&quot;code&quot;:&quot;not_found&quot;}</code></td></tr><tr><td><code>409</code></td><td><code>{&quot;ok&quot;:false,&quot;code&quot;:&quot;already_running&quot;}</code></td></tr><tr><td><code>503</code></td><td><code>{&quot;ok&quot;:false,&quot;code&quot;:&quot;spawn_failed&quot;}</code></td></tr></tbody></table><p>Authentication comparison is constant-time. Unauthorized bodies are bounded and discarded without launching work.</p><h2 id="core-authorization-contract" tabindex="-1">Core authorization contract <a class="header-anchor" href="#core-authorization-contract" aria-label="Permalink to &quot;Core authorization contract&quot;">​</a></h2><p>Before dispatch, the core must:</p><ol><li>resolve the exact task;</li><li>assign an open unowned task to <code>agent:fixer</code>, or verify that ownership;</li><li>require a dispatchable status (<code>claimed</code>, <code>investigating</code>, <code>waiting_operator</code>, <code>blocked</code>);</li><li>persist and commit <code>task.fixer_dispatch_requested</code> bound to task, owner and authorizing actor;</li><li>re-read and validate that authorization before sending only <code>task_id</code>;</li><li>audit the normalized dispatch outcome.</li></ol><p>The supervisor does not receive canonical task data. The launched agent must retrieve the task through MCP and independently verify ownership and dispatch history.</p><h2 id="worker-process-boundary" tabindex="-1">Worker process boundary <a class="header-anchor" href="#worker-process-boundary" aria-label="Permalink to &quot;Worker process boundary&quot;">​</a></h2><p>One process per task is launched with an exact no-shell argument vector using <code>opencode --pure run</code>, fixed agent <code>homelab-fixer</code>, JSON output and a fixed project directory. Child stdin/stdout/stderr are not an application protocol. The child environment is allowlisted and excludes application/provider credentials. Timeout is bounded to 30–7200 seconds; timeout terminates then kills the child if necessary.</p><h2 id="compatibility-conformance-and-rollback" tabindex="-1">Compatibility, conformance and rollback <a class="header-anchor" href="#compatibility-conformance-and-rollback" aria-label="Permalink to &quot;Compatibility, conformance and rollback&quot;">​</a></h2><p>Compatible v1 client/supervisor pairs must test exact payload, body bounds, constant-time secret auth, loopback binding, duplicate locking, spawn failure, exact no-shell launch, environment filtering and core event/ownership binding.</p><p>Rollback disables <code>FIXER_DISPATCH_ENABLED</code>, stops the supervisor, revokes its dedicated MCP token and releases tasks still owned by <code>agent:fixer</code>. Chat, Router and interactive OpenCode remain unaffected. Breaking HTTP, identity or authorization semantics require v2.</p>',28)])])}const k=t(s,[["render",n]]);export{u as __pageData,k as default};
